  1447          a->name[1] = (FT_String)( ( a->tag >> 16 ) & 0xFF );
  1448          a->name[2] = (FT_String)( ( a->tag >>  8 ) & 0xFF );
  1449          a->name[3] = (FT_String)( ( a->tag       ) & 0xFF );
  1450          a->name[4] = '\0';
