  1500          (FT_Fixed*)&( mmvar->namedstyle[mmvar->num_namedstyles] );
  1501
  1502        for ( n = 0; n < mmvar->num_namedstyles; n++ )
  1503        {
  1504          mmvar->namedstyle[n].coords  = next_coords;
  1505          next_coords                 += mmvar->num_axis;
  1506        }
  1507
  1508        a         = mmvar->axis;
  1509        next_name = (FT_String*)next_coords;
  1510        for ( n = 0; n < mmvar->num_axis; n++ )
  1511        {
  1512          a->name = next_name;
  1513
  1514          /* standard PostScript names for some standard apple tags */
  1515          if ( a->tag == TTAG_wght )
  1516            a->name = (char*)"Weight";
