  1536    /*************************************************************************/
  1537    /*                                                                       */
  1538    /* <Function>                                                            */
  1539    /*    TT_Set_MM_Blend                                                    */
  1540    /*                                                                       */
  1541    /* <Description>                                                         */
  1542    /*    Set the blend (normalized) coordinates for this instance of the    */
  1543    /*    font.  Check that the `gvar' table is reasonable and does some     */
  1544    /*    initial preparation.                                               */
  1545    /*                                                                       */
  1546    /* <InOut>                                                               */
