  1649        {
  1650          if ( blend->normalizedcoords[i] != 0 )
  1651          {
  1652            manageCvt = mcvt_load;
  1653            break;
  1654          }
  1655        }
  1656
  1657        /* If we don't change the blend coords then we don't need to do  */
  1658        /* anything to the cvt table.  It will be correct.  Otherwise we */
  1659        /* no longer have the original cvt (it was modified when we set  */
  1660        /* the blend last time), so we must reload and then modify it.   */
  1661      }
  1662
  1663      blend->num_axis = mmvar->num_axis;
  1664      FT_MEM_COPY( blend->normalizedcoords,
  1665                   coords,
  1666                   num_coords * sizeof ( FT_Fixed ) );
  1667
  1668      face->doblend = TRUE;
  1669
  1670      if ( face->cvt != NULL )
  1671      {
  1672        switch ( manageCvt )
  1673        {
  1674        case mcvt_load:
  1675          /* The cvt table has been loaded already; every time we change the */
  1676          /* blend we may need to reload and remodify the cvt table.         */
  1677          FT_FREE( face->cvt );
  1678          face->cvt = NULL;
  1679
  1680          error = tt_face_load_cvt( face, face->root.stream );
  1681          break;
  1682
  1683        case mcvt_modify:
  1684          /* The original cvt table is in memory.  All we need to do is */
  1685          /* apply the `cvar' table (if any).                           */
  1686          error = tt_face_vary_cvt( face, face->root.stream );
  1687          break;
  1688
  1689        case mcvt_retain:
  1690          /* The cvt table is correct for this set of coordinates. */
  1691          break;
  1692        }
  1693      }
  1694
  1695      face->is_default_instance = is_default_instance;
  1696
  1697    Exit:
  1698      return error;

